<?php
session_start();header('Content-Type: application/json; charset=utf-8');
require_once(__DIR__.'/../../../Database/db/db.php');require_once(__DIR__.'/../../../utils/security/csrf/csrf.php');
$respond=static function(int $status,array $body):never{http_response_code($status);echo json_encode($body);exit;};
if($_SERVER['REQUEST_METHOD']!=='POST')$respond(405,['success'=>false,'message'=>'POST required']);
if(($_SESSION['role']??'')!=='student'||empty($_SESSION['user_id']))$respond(401,['success'=>false,'message'=>'Student sign-in required']);
$data=json_decode(file_get_contents('php://input'),true)?:[];$lessonId=filter_var($data['lesson_id']??null,FILTER_VALIDATE_INT);$token=$data['csrf_token']??($_SERVER['HTTP_X_CSRF_TOKEN']??'');if(!$lessonId)$respond(422,['success'=>false,'message'=>'Valid lesson ID required']);if(!is_string($token)||!CSRF::validateToken($token))$respond(403,['success'=>false,'message'=>'Security token expired. Refresh the page.']);
try{$pdo=get_db();$userId=(int)$_SESSION['user_id'];$check=$pdo->prepare("SELECT cm.course_id FROM course_lessons cl JOIN course_modules cm ON cm.id=cl.module_id JOIN enrollments e ON e.course_id=cm.course_id AND e.user_id=? AND e.status IN ('active','completed') WHERE cl.id=? AND cl.is_active=1 AND cm.is_active=1 LIMIT 1");$check->execute([$userId,$lessonId]);$courseId=$check->fetchColumn();if(!$courseId)$respond(403,['success'=>false,'message'=>'You must be enrolled in this course to update progress.']);$pdo->beginTransaction();$find=$pdo->prepare('SELECT id FROM lesson_progress WHERE user_id=? AND lesson_id=? ORDER BY id LIMIT 1');$find->execute([$userId,$lessonId]);$rowId=$find->fetchColumn();if($rowId){$save=$pdo->prepare("UPDATE lesson_progress SET status='completed',progress_percentage=100,completed_at=NOW() WHERE id=? AND user_id=?");$save->execute([$rowId,$userId]);}else{$save=$pdo->prepare("INSERT INTO lesson_progress (user_id,lesson_id,status,progress_percentage,completed_at) VALUES (?,?,'completed',100,NOW())");$save->execute([$userId,$lessonId]);}$counts=$pdo->prepare("SELECT COUNT(cl.id) total,SUM(CASE WHEN lp.status='completed' THEN 1 ELSE 0 END) completed FROM course_modules cm JOIN course_lessons cl ON cl.module_id=cm.id LEFT JOIN lesson_progress lp ON lp.lesson_id=cl.id AND lp.user_id=? AND lp.status='completed' WHERE cm.course_id=? AND cm.is_active=1 AND cl.is_active=1");$counts->execute([$userId,$courseId]);$stats=$counts->fetch(PDO::FETCH_ASSOC);$total=(int)($stats['total']??0);$complete=(int)($stats['completed']??0);$progress=$total?round(100*$complete/$total,2):0;$update=$pdo->prepare("UPDATE enrollments SET progress=?,status=CASE WHEN ? >= 100 THEN 'completed' ELSE 'active' END,completed_at=CASE WHEN ? >= 100 THEN COALESCE(completed_at,NOW()) ELSE completed_at END WHERE user_id=? AND course_id=?");$update->execute([$progress,$progress,$progress,$userId,$courseId]);$pdo->commit();$respond(200,['success'=>true,'message'=>'Lesson marked complete','completed_lessons'=>$complete,'total_lessons'=>$total,'progress'=>$progress]);}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log('LMS lesson completion failed: '.$e->getMessage());$respond(500,['success'=>false,'message'=>'Unable to save progress right now.']);}
